-- =============================================================================
-- StaziaMed, CARGA DAS PROVAS CORRIGIDAS, parte 2 (Revalida 2020, revalida-2020): texto fiel ao caderno oficial do Inep.
-- Gerado por scripts/carga-provas/gerar-correcoes.mjs (ramo carga-provas). Não edite à mão.
-- O que faz: 49 correções de texto em 24 questões (25 campos: enunciado ou alternativa).
--   * Cada campo só é trocado se o texto no banco ainda é EXATAMENTE o de 12/10/2026 (o que a revisão comparou com o PDF).
--     Se alguém mudou esse texto depois, o campo é PULADO e aparece na lista do fim. Nada é apagado.
--   * O texto antigo fica no histórico da questão (Administração > Questões > Editar > Ver histórico de mudanças), com o motivo.
--   * NÃO mexe em gabarito, situação (anulada), explicações, conduta esperada, "o que a questão avalia", tema, figuras.
--   * Regra do sistema (migração 9500): se a questão tinha Análise Stazia publicada, ela sai do ar (explicava o texto antigo);
--     a contagem aparece no fim.
-- Como colar: editor SQL do Supabase, o arquivo INTEIRO, Run. A primeira linha do resultado começa com "OK:" (ou "ATENÇÃO:" se
-- algum campo foi pulado; mostre ao Claude). Pode colar de novo: a segunda vez não muda nada.
-- =============================================================================
create temp table if not exists _carga_texto_resultado (prova text, questao text, codigo text, campo text, situacao text);
delete from _carga_texto_resultado where prova = 'revalida-2020';

do $carga_texto$
declare
  v_dados constant jsonb := $carga_dados$[{"id":"revalida_2020_1_q006","code":"REV-2020-Q006","campos":{"statement":{"antes_md5":"33572d5c57dfa31e69849b4eadc08641","depois":"Uma mulher com 48 anos de idade vai a uma consulta na Unidade Básica de Saúde com queixa de calorões há três meses. As ondas de calor começam de repente, percorrem o tórax, pescoço e cabeça, geram suor abundante e terminam espontaneamente após alguns minutos. Ultimamente, os fogachos acontecem cerca de 3 a 4 vezes por dia e, às vezes, ocorrem durante a noite, atrapalhando o sono. A paciente está ficando cansada e irritada desde que o sintoma começou. Usa como método contraceptivo a laqueadura tubária. Ela teve ciclos menstruais irregulares nos últimos anos (menstruava a cada 2 ou 3 meses) e está em amenorreia há 6 meses. Deseja alguma solução para os calorões que a estão “deixando louca”. Não fuma, nega doenças crônicas e nega história de câncer de mama ou endométrio. Sua história familiar é negativa para doenças ginecológicas. Em seu exame físico, apresenta IMC = 23,5 kg/m², PA = 110 x 70 mmHg e exame ginecológico e de mamas sem alterações dignas de nota. Todos os exames complementares de rotina estão normais. Considerando os dados clínicos da paciente, assinale a alternativa que apresenta a conduta adequada."}}},{"id":"revalida_2020_1_q009","code":"REV-2020-Q009","campos":{"statement":{"antes_md5":"fd46bcab5b59b3acabe47d83c8954f28","depois":"Uma mulher com 36 anos de idade, obesa e multípara, é admitida no pronto-socorro com quadro de febre alta com calafrios, dor no hipocôndrio direito e icterícia. Ela tem histórico de dor abdominal recorrente no hipocôndrio direito, geralmente associada à ingestão de alimentação gordurosa. Ao chegar a essa unidade hospitalar, encontra-se torporosa, febril (39,6 ºC), com PA = 90 x 60 mmHg, reagindo com fácies de dor à compressão do hipocôndrio direito, mas com sinal de Murphy ausente. Os exames laboratoriais da paciente revelam leucócitos = 22.000/mm³ (valor de referência: 6 000 a 10 000/mm³), com 17 % de bastões e 3 % de metamielócitos e bilirrubina direta = 4,8 mg/dL (valor de referência: até 0,3 mg/dL), fosfatase alcalina = 420 UI/L (valor de referência: 70 a 192 UI/L) e gama-glutamil transferase = 302 UI/L (valor de referência: 70 a 192 UI/L). A ultrassonografia abdominal da paciente mostra a presença de dilatação das vias biliares extra-hepáticas, e a vesícula biliar com algumas imagens hiperdensas e com sombra acústica posterior. Diante desse quadro clínico, qual é o diagnóstico correto?"}}},{"id":"revalida_2020_1_q015","code":"REV-2020-Q015","campos":{"statement":{"antes_md5":"e550e7228f1531fe761bd66d8942fe5b","depois":"Um adolescente com 11 anos de idade é atendido no pronto-socorro com história de dor e inchaço em joelho esquerdo há 5 dias. Ele conta que, há 2 dias, iniciou com febre, dificuldade para deambular e aumento da dor e do inchaço na região. A mãe relata recusa alimentar e palidez cutânea há 1 dia. O adolescente apresenta antecedente de trauma local durante partida de futebol há 1 semana e refere o uso de anti-inflamatório não esteroidal desde então, sem melhora do quadro. Ao exame físico, apresenta-se em regular estado geral, com palidez cutânea, febril (temperatura axilar = 38,2 ºC), eupneico, anictérico, acianótico, com tempo de enchimento capilar de 3 segundos e pressão arterial normal para a idade. Apresenta, ainda, edema, rubor, calor e dor no joelho esquerdo, com bloqueio à tentativa de mobilização. O resultado do hemograma mostra leucocitose com desvio à esquerda. Também foram observados proteína C reativa e VHS elevados. Nesse caso, quais são o agente etiológico mais provável e a antibioticoterapia endovenosa indicada?"}}},{"id":"revalida_2020_1_q016","code":"REV-2020-Q016","campos":{"statement":{"antes_md5":"70da5017e66d044530a7fae866e9c628","depois":"Uma mulher com 20 anos de idade, com 10 semanas de gestação, retorna para consulta de pré-natal com exames de rotina. A urocultura apresentou crescimento bacteriano maior que 10⁵ UFC/mL (unidades formadoras de colônias por mL). A paciente relatou aumento da frequência urinária, entretanto negou sintomas como disúria, urgência miccional, noctúria, dor suprapúbica ou febre. Nesse caso, o diagnóstico e o tratamento antimicrobiano são, respectivamente,"}}},{"id":"revalida_2020_1_q019","code":"REV-2020-Q019","campos":{"statement":{"antes_md5":"e4a0c1c0a1ac30a7800ca3cca115ab79","depois":"Um homem com 54 anos de idade, transplantado renal há 3 meses, apresenta, há cerca de 7 dias, febre elevada (> 40 ºC), tosse pouco produtiva (escarro pouco purulento) e dor torácica à esquerda. Ele procurou o serviço onde realizou o transplante de órgão, sendo observada a presença de febre elevada e ausculta pulmonar com estertores crepitantes difusos, além de semiologia compatível com derrame pleural à esquerda. O Gram de escarro não mostrou patógenos, mas apenas alguns polimorfonucleares. A Tomografia Computadorizada de Tórax (TCT), realizada no mesmo dia, revelou opacidades alveolares arredondadas e derrame pleural leve à esquerda. Como o paciente respondeu bem à administração de antitérmico, mantendo bom estado hemodinâmico e padrão respiratório satisfatório, foi liberado para casa com prescrição de amoxicilina-clavulanato. No entanto, após 4 dias de tratamento, mantinha-se febril, sem melhora do quadro clínico. Nova TCT revelou que algumas das opacidades parenquimatosas haviam evoluído com escavação central. Foi formulada a hipótese de pneumonia por Legionella pneumophila. Em função de o paciente estar em tratamento imunossupressor com ciclosporina e tacrolimus, qual é o tratamento antimicrobiano adequado a ser prescrito?"}}},{"id":"revalida_2020_1_q028","code":"REV-2020-Q028","campos":{"statement":{"antes_md5":"fd88ea967cc4aaee761ac6bc495b5e92","depois":"Um paciente com 30 anos de idade, internado na Unidade de Terapia Intensiva com diagnóstico de abscesso renal, intubado e em ventilação mecânica, apresentou, na admissão, os seguintes sinais vitais: PA = 90 x 40 mmHg, febre de 39 ºC, FC = 114 bpm, FR = 23 irpm, Escala de Ramsay de 5, PaO₂/FiO₂ de 350. Após ressuscitação volêmica com cristaloides, apresentou melhora do quadro hemodinâmico (PA = 110 x 70 mmHg). Exames laboratoriais mostraram os seguintes resultados: bilirrubina total = 1,1 mg/dL (valor de referência: 0,8 a 1,2 mg/dL), creatinina = 1,9 mg/dL (valor de referência: 0,8 a 1,2 mg/dL) e lactato = 2,2 mmol/L (valor de referência: < 2 mmol/L). A definição atual do quadro clínico desse paciente é"}}},{"id":"revalida_2020_1_q032","code":"REV-2020-Q032","campos":{"statement":{"antes_md5":"ffdd5d58f6a651cece5e309b99cfa58a","depois":"Uma gestante com 24 anos de idade, primigesta de 28 semanas, em seguimento pré-natal na Unidade Básica de Saúde, comparece a uma consulta eventual, relatando início, há 5 dias, de tosse, febre (até 38 ºC), inapetência e perda de 1 kg. Foi coletado material de nasofaringe por swab, com SARS-CoV-2 detectado em teste molecular (RT-qPCR). A paciente trabalha como balconista de shopping center. Para essa paciente, segundo orientações do Ministério da Saúde, deve-se"}}},{"id":"revalida_2020_1_q034","code":"REV-2020-Q034","campos":{"statement":{"antes_md5":"6f6ec92b8d032d80b940cef235dc2c79","depois":"Um homem com 39 anos de idade, previamente hígido, é atendido em centro de saúde com lesão peniana, mal-estar e febre baixa há 5 dias. O paciente nega descarga uretral e nega lesões penianas prévias. Não tem parceira sexual estável, tendo relações sexuais desprotegidas com diferentes mulheres esporadicamente. Em seu exame físico, apresenta temperatura axilar = 37,8 ºC e está corado, hidratado e anictérico. Há linfonodos axilares, epitrocleares e inguinais palpáveis, pequenos, fibrioelásticos. Verifica-se lesão ulcerada e úmida em corpo peniano. O teste rápido para sífilis realizado no momento da consulta foi positivo. Não há relato de tratamento com antimicrobianos no último ano. Relata que, há cerca de 10 anos, ao tomar penicilina benzatina intramuscular para tratar faringite, teve dor no local da aplicação, sem lesões e com remissão espontânea. Nesse momento, qual é a conduta correta para esse paciente?"}}},{"id":"revalida_2020_1_q044","code":"REV-2020-Q044","campos":{"statement":{"antes_md5":"7587ad26d1f16913124859f350e69736","depois":"Uma mulher com 44 anos de idade é encaminhada para avaliação de nódulos mamários múltiplos, inicialmente atribuídos a possível doença fibrocística benigna da mama. A razão do encaminhamento ao especialista é a preocupação da paciente com o fato de uma tia paterna, com 68 anos de idade, ter sido recentemente diagnosticada com câncer de mama (adenocarcinoma ductal infiltrante). A paciente é multípara (G4P5), tendo sua primeira gestação ocorrido aos 36 anos de idade. Amamentou todos os filhos por pelo menos 1 ano. Sua menarca foi tardia, ocorrendo aos 16 anos de idade. Relata que seus ciclos menstruais são indolores e regulares, a cada 28 dias (3 dias de duração), com fluxo em volume normal. Mantém relações sexuais regulares, com parceiro único e sem uso de preservativo. Ela nega possuir comorbidades e alergias. No exame das mamas, são palpados múltiplos nódulos de consistência fibroelástica bilaterais, no meio dos quais é palpado um nódulo sólido, indolor e pouco móvel, de 2,0 cm de diâmetro, localizado no quadrante superior externo da mama esquerda; não há alterações cutâneas locais nem linfonodomegalias satélites, axilares, supraclaviculares ou cervicais. No exame físico geral, a paciente se encontra em bom estado, corada, com IMC = 23,5 kg/m². Além do nódulo sólido palpável, qual é o outro fator de risco para câncer de mama que a paciente apresenta?"}}},{"id":"revalida_2020_1_q045","code":"REV-2020-Q045","campos":{"statement":{"antes_md5":"8a7743232de91cfa845c4c78a990c015","depois":"Uma pré-escolar com 4 anos de idade é atendida no pronto-socorro com história de febre alta (40 ºC) há 3 dias, indisposição e dores no corpo, vômitos e diarreia. No momento, queixa-se de dor abdominal intensa e contínua. Em seu exame físico, os resultados foram os seguintes: FC = 120 bpm, FR = 25 irpm, temperatura axilar = 37,5 ºC, mucosas úmidas, coradas, anictéricas; ausculta cardíaca e respiratória normais, abdome levemente distendido, doloroso difusamente à palpação, sem sinais de irritação peritoneal, fígado palpável a 3 cm do rebordo costal direito. Há petéquias esparsas e exantema máculo-papular em face, tronco, membros superiores e inferiores, incluindo palmas das mãos. Suas extremidades estão aquecidas e bem perfundidas. Foi realizado hemograma que apresentou os seguintes valores: Ht = 45 % (valor de referência: 37 a 40 %); Hb = 15,2 g/dL (valor de referência: 12,6 ± 1,5 g/dL), leucócitos totais = 3 500/mm³ (valor de referência: 5 000 a 12 000/mm³, bastões = 2 %, segmentados = 50 %, linfócitos = 30 %, monócitos = 10 %, eosinófilos = 8 %, plaquetas = 50 000/mm³ (valor de referência: 150 000 a 450 000/mm³). Quais são, respectivamente, o diagnóstico e a conduta médica inicial adequados?"}}},{"id":"revalida_2020_1_q046","code":"REV-2020-Q046","campos":{"statement":{"antes_md5":"df4d4d9e31bfc155dfcf3d5c99e67130","depois":"Uma gestante, no curso da 12.ª semana de gestação, vai ao ambulatório de obstetrícia referenciado de sua Unidade Básica de Saúde com o seguinte encaminhamento: “Encaminho primigesta com 23 anos de idade por ter apresentado, em seus exames de rotina do pré-natal, uma glicemia de jejum de 140 mg/dL”. No momento, a paciente encontrava-se assintomática e já trazia um segundo resultado de glicemia de jejum que demonstrava um valor de 148 mg/dL. O obstetra do ambulatório, segundo as recomendações mais atualizadas da OMS e da Sociedade Brasileira de Diabetes, deve"}}},{"id":"revalida_2020_1_q048","code":"REV-2020-Q048","campos":{"statement":{"antes_md5":"2fb36fcdb1edd1806643294bc492b0a4","depois":"Uma paciente com 34 anos de idade, vítima de acidente automobilístico, apresentando trauma abdominal contuso sem evidências de lesões em outros segmentos corpóreos, foi levada ao pronto-socorro do Centro de Referência de Trauma de nível terciário para atendimento. No atendimento em cena pela equipe de suporte avançado do Serviço de Atendimento Móvel de Urgência (SAMU), foram infundidos 500 mL de ringer lactato. No exame físico da paciente, obteve-se os seguintes resultados: FC = 110 bpm, enchimento capilar = 6 segundos, PA = 100 x 70 mmHg, Glasgow = 15. Houve normalização dos sinais vitais após a infusão de mais 500 mL de solução cristaloide no atendimento inicial. Os exames laboratoriais mostraram os seguintes resultados: Hb = 10,5 g/dL (valor de referência: 12 a 14 g/dL), Ht = 31 % (valor de referência: 35 a 45 %), lactato = 2,8 mmol/L (valor de referência: < 2,0 mmol/L), INR = 1,0 (valor de referência: 0,8 a 1,2), fibrinogênio = 200 mg/dL (valor de referência: 185,0 a 400,0 mg/dL), plaquetas = 120 000/mm³ (valor de referência: 100 000 a 424 000/mm³). A tomografia computadorizada de abdome com contraste endovenoso é mostrada na imagem a seguir. Não foram evidenciadas outras lesões no abdome. Tomografia computadorizada de abdome Com base na história clínica, nos dados do exame físico e na imagem da tomografia, a conduta médica adequada é indicar"}}},{"id":"revalida_2020_1_q051","code":"REV-2020-Q051","campos":{"statement":{"antes_md5":"ad1ff3d9c04fbc3e51e1f5bb9868b64f","depois":"Uma gestante, no curso da 24.ª semana de gestação, comparece à consulta de rotina de pré-natal. Informa já ter tido um aborto com 7 semanas e um parto vaginal com 34 semanas. No momento, está sem queixas e apresenta exame físico dentro da normalidade. Traz consigo ultrassonografia gestacional que revela gestação única, tópica, com 24 semanas (corrigidas), feto com apresentação cefálica, placenta anterior e com grau zero de maturidade, quantidade de líquido amniótico e peso fetal normais para a idade gestacional, colo uterino fechado medindo 2,9 cm (valor de referência: > 2,5 cm). Apresenta também resultado de exame de urocultura que revela E. coli com 10⁵ Unidades Formadoras de Colônias. O médico prescreve cefalexina e progesterona para essa paciente. Nesse caso, a prescrição de progesterona se justifica porque a gestante apresenta"}}},{"id":"revalida_2020_1_q056","code":"REV-2020-Q056","campos":{"statement":{"antes_md5":"b5be545efbe97ddf3f1ae813aa6e70f1","depois":"Uma adolescente com 18 anos de idade chega à Unidade Básica de Saúde com queixa de sinusorragia, dispareunia e corrimento amarelado sem odor e sem prurido. A paciente nega outras queixas. Ao realizar exame físico, os resultados foram os seguintes: PA = 120 x 75 mmHg, pulso = 70 bpm, temperatura axilar = 36,5 ºC. Seu abdome está plano, flácido e indolor à palpação. Em exame especular, percebe-se corrimento amarelado sem bolhas e sem grumos presentes na vagina e no orifício cervical externo, colo uterino sangrante ao toque e doloroso à mobilização. Seu pH vaginal está próximo de 4,0 e o teste de Whiff deu negativo. Qual é o provável agente etiológico do quadro clínico apresentado por essa adolescente?"}}},{"id":"revalida_2020_1_q059","code":"REV-2020-Q059","campos":{"statement":{"antes_md5":"5b6de1d61553dcba6163a528879b1f3f","depois":"Uma mulher com 64 anos de idade é encaminhada para investigação diagnóstica de quadro de tosse seca e dispneia ao realizar esforços. A paciente é portadora, há 3 décadas, de hipertensão arterial sistêmica, sendo tabagista e etilista social. Seu exame físico revela IMC = 33 kg/m², eupneica em repouso, mas com acrocianose (+/4+) e murmúrio vesicular reduzido difusamente, sendo auscultados sibilos esparsos em todo tórax. O ritmo cardíaco é regular, em 2 tempos, com 2.ª bulha hiperfonética em foco pulmonar. Há turgência de veia jugular quando a cabeceira da maca é elevada a 45 graus, além de edema de membros inferiores (2+/4+). A paciente traz à consulta uma espirometria realizada recentemente que evidencia um volume expiratório forçado no 1.º segundo (VEF1) reduzido (68 % do previsto com base em sua idade e altura), sendo a relação entre esse parâmetro e a capacidade vital forçada (VEF1/CVF) inferior a 70 %; não há elevação de 20 % ou aumento superior a 200 mL em nenhum desses dois parâmetros espirométricos após a administração de broncodilatador. Com base no caso clínico e no resultado da espirometria, qual é o diagnóstico da paciente?"}}},{"id":"revalida_2020_1_q064","code":"REV-2020-Q064","campos":{"statement":{"antes_md5":"7ce9be26fa059a169b39c570a79442f1","depois":"Um homem com 36 anos de idade comparece à Unidade Básica de Saúde queixando-se de lesão cutânea localizada no membro superior direito. Ele informa que, cerca de 10 dias após realizar atividades de jardinagem em seu sítio, utilizando a enxertia de algumas de suas laranjeiras, observou o aparecimento de uma pápula dolorosa no 1.º quirodáctilo direito. Nos dias subsequentes, essa lesão evoluiu com ulceração local, surgindo, posteriormente, lesões similares no mesmo antebraço. Durante o exame, são observadas pápulas ulceradas na região assinalada, havendo aspecto sugestivo de disseminação linfangítica do processo. O médico suspeita de uma determinada dermatose de etiologia infecciosa. Com base na apresentação clínica e considerando a história epidemiológica relatada, o agente etiológico e o meio de cultura em agar adequado para sua detecção são, respectivamente,"}}},{"id":"revalida_2020_1_q065","code":"REV-2020-Q065","campos":{"statement":{"antes_md5":"06c21b024c8d45a801d937ea5b33afe3","depois":"Um lactente com 1 mês de vida, nascido a termo de parto normal sem intercorrências, em aleitamento materno exclusivo, retornou à Unidade Básica de Saúde para consulta de puericultura. A mãe começou a apresentar febre (temperatura axilar = 38 ºC) há 2 dias e encontra-se em bom estado geral. Apresenta dor, calor, edema e rubor em quadrante superior esquerdo da mama direita, sendo indicado tratamento domiciliar com cefalexina e ibuprofeno. Nesse caso, o aleitamento materno deverá"}}},{"id":"revalida_2020_1_q072","code":"REV-2020-Q072","campos":{"statement":{"antes_md5":"272730c039d9354acf1c271159575ea9","depois":"Uma mãe leva seu filho de 5 anos de idade para atendimento, na Unidade Básica de Saúde, relatando febre persistente há 24 horas, diminuição do apetite, náuseas e vômitos. A criança amanheceu febril, com cefaleia e sede. A mãe relata que a criança frequentou uma festa de aniversário há cerca de 5 dias. Ela tem vacinação em dia. No exame físico, os resultados de sua avaliação foram os seguintes: pouco reativa; FC = 130 bpm; FR= 30 irpm; temperatura axilar = 38,8 °C; Sat. O₂ = 96 %; mucosas desidratadas 3+/4+; petéquias puntiformes em membros inferiores, tórax e abdome. Ele possui dor à flexão da coluna cervical. Nesse caso, qual é a conduta médica adequada?"}}},{"id":"revalida_2020_1_q073","code":"REV-2020-Q073","campos":{"statement":{"antes_md5":"a36513455ad4e692d9cc8721d6d335cb","depois":"Um paciente com 30 anos de idade, vítima de traumatismo há 5 dias, necessitou de laparotomia por trauma fechado de abdome para rafia de lesão hepática, esplenectomia e rafia de alça de delgado. Ele encontra-se em estado grave na unidade de terapia intensiva, com necessidade de aminas vasoativas (3 mL/h de noradrenalina) e em ventilação mecânica. Há 24 horas foi passado cateter de Swan-Ganz através de veia subclávia direita para melhor monitorização dos parâmetros hemodinâmicos. Hoje apresenta hipotensão grave (PA = 70 x 20 mmHg), refratária à reposição volêmica e necessitando de aumento de noradrenalina para 18 mL/h. Os parâmetros do Swan-Ganz são os seguintes: índice cardíaco = 2,5 L/min.m² (valor de referência: 2,8 a 4,0 L/min.m²), resistência vascular periférica = 2 000 dina.seg/cm-5 (valor de referência: 770 a 1 500 dina.seg/cm-5), pressão capilar pulmonar = 1 cmH₂0 (valor de referência: 2 a 12 cmH₂0), pressão venosa central (PVC) = 15 cmH₂0 (valor de referência: 0 a 9 cmH₂0). A natureza provável do choque desse paciente é"}}},{"id":"revalida_2020_1_q075","code":"REV-2020-Q075","campos":{"statement":{"antes_md5":"a26c6cbef50e787f6a4333c8d499d86b","depois":"Um lactente com 2 meses de idade é atendido na emergência, acompanhado pela mãe, que relata vômitos pós-prandiais desde os 15 dias de vida, com piora progressiva em frequência e intensidade. Ela conta que, após tais episódios eméticos, o lactente chora e parece ter fome. Informa, ainda, que seu filho nasceu a termo, com peso de 3 000 g e 49 cm de comprimento e que os testes de triagem neonatal foram normais. Ela nega a ocorrência de doenças gestacionais e perinatais. Ao exame físico, o lactente apresenta-se emagrecido (peso = 3 200 g), ativo, acianótico, anictérico, desidratado (1+/4+) e corado, com abdome distendido, especialmente na região epigástrica, notando-se ausência de hepatoesplenomegalia e presença de ondas de Kussmaul observadas após a alimentação. Os exames laboratoriais iniciais revelam pH = 7,5 (valor de referência: 7,35 a 7,45); HCO₃ = 27 mEq/L (valor de referência: 23 a 28 mEq/L); Na = 135 mmol/L (valor de referência: 136 a 145 mmol/L); Cl = 95 mmol/L (valor de referência: 98 a 106 mmol/L) e K = 4,5 mmol/L (valor de referência: 3,5 a 5,5 mmol/L). Nesse caso, a conduta médica adequada é"},"D":{"antes_md5":"7eae4f4ab50e95adb77d6a93d78ed4a2","depois":"prescrever expansão com soro fisiológico 0,9 % e infusão de hidrocortisona 50 mg/m² subcutânea/dia."}}},{"id":"revalida_2020_1_q080","code":"REV-2020-Q080","campos":{"statement":{"antes_md5":"155c0b68750ac8aa8bb07ad8e21b23aa","depois":"Um pré-escolar com 3 anos de idade, previamente hígido, é atendido no pronto-socorro. A mãe relata que seu filho apresentou manchas no corpo há 2 dias. Além disso, refere que a criança esteve resfriada no mês anterior e que melhorou após 5 dias. Durante o exame físico, estava afebril, alerta, com múltiplas petéquias em membros e tronco, pequenos hematomas em joelhos, ausência de visceromegalias ou linfonodomegalia. O exame de esfregaço de sangue periférico mostra plaquetas de 57 000/mm³ (valor de referência: 150 000 a 450 000/mm³), com macroplaquetas; células vermelhas e brancas com morfologia e quantidade normais. Nesse caso, o diagnóstico provável e a conduta adequada são, respectivamente,"}}},{"id":"revalida_2020_1_q085","code":"REV-2020-Q085","campos":{"statement":{"antes_md5":"12df1b64a90e003bc6d6eb0c30cceb05","depois":"Um recém-nascido a termo, com 24 horas de vida e peso de nascimento de 3 200 g, realiza o teste de triagem neonatal para cardiopatia congênita crítica (Teste do Coraçãozinho) com os seguintes resultados: Saturação de O₂ em membro superior direito (MSD) de 97 % e em membro inferior direito (MID) de 93 %. A conclusão do resultado do teste e a conduta médica indicada em relação ao caso são, respectivamente,"}}},{"id":"revalida_2020_1_q095","code":"REV-2020-Q095","campos":{"statement":{"antes_md5":"cf4f71de53e664c64789d550769480cc","depois":"Uma lactente com 1 ano e 10 meses de idade, previamente hígida, foi atendida no pronto-socorro com quadro de febre e irritabilidade iniciado há 72 horas. Não foram encontradas alterações em exame físico realizado na criança. Procedeu-se, então, à coleta de urina tipo 1 por sondagem vesical e hemograma. A criança foi encaminhada ao ambulatório para verificação dos exames. O hemograma revelou Hb = 11,8 g/dL (valor de referência: 12,6 ± 1,5 g/dL), Ht = 38 % (valor de referência: 37 a 40 %), leucócitos = 18 000 mm³ (valor de referência: 5 000 a 15 000/mm³), plaquetas = 300 000 mm³ (valor de referência: 150 000 a 450 000/mm³), segmentados = 60 %, linfócitos = 37 % e monócitos = 3 %. O exame de urina tipo 1 apresentou densidade = 1 015 (valor de referência: 1 005 a 1 030), pH = 5,7 (valor de referência: 5,5 a 7,5), leucócitos = 180 000/mL (valor de referência: até 10 000/mL), hemácias = 10 000/mL (valor de referência: até 10 000/mL), cilindros piocitários raros, nitrito positivo e a bacterioscopia mostrou a presença de agente Gram negativo. Diante desse quadro clínico, a conduta médica indicada é"}}},{"id":"revalida_2020_1_q099","code":"REV-2020-Q099","campos":{"statement":{"antes_md5":"8ee2f7fe8b60eb7848433a3c19d13829","depois":"Um homem com 50 anos de idade é internado em hospital terciário para investigação diagnóstica e tratamento de quadro caracterizado por dispneia aos moderados esforços. Há relato, ainda, de precordialgia em aperto, com duração de cerca de 5 minutos, precipitada por esforços e aliviada com o repouso, além da ocorrência de 2 episódios de síncope nos últimos 12 meses. Ao realizar exame físico, constatou-se que o paciente se encontra em regular estado geral, corado, acianótico, eupneico, com a cabeceira do leito elevada a 30 graus. Seu ritmo cardíaco é regular, em 3 tempos, com a presença de 4.ª bulha e a existência de um sopro mesossistólico 3+/6+ mais audível no 2.º espaço intercostal direito, na borda esternal; os pulsos arteriais são do tipo parvus et tardus. A ausculta pulmonar apresenta discretos estertores crepitantes em bases. Não há edema de membros inferiores. A radiografia de tórax (PA e perfil) mostra leve dilatação da raiz da aorta, área cardíaca normal e presença de calcificações mitro-aórticas. É solicitado, então, um ecocardiograma transtorácico que revela área valvar aórtica de 0,9 cm² (normal: 3 a 4 cm²), sendo o gradiente ventrículo esquerdo (VE) – aorta de 55 mmHg e velocidade máxima de fluxo transvalvar de 4,5 metros/segundo (normal = inferior a 2 m/seg); fração de ejeção do VE é de 52 %. Frente ao processo de avaliação diagnóstica e ao estabelecimento de plano terapêutico neste momento, qual é a conduta médica indicada para o paciente e sua justificativa?"}}}]$carga_dados$::jsonb;
  r jsonb;
  c record;
  q public.questions;
  v_statement text;
  v_options jsonb;
  v_atual text;
  v_situacao text;
  v_muda boolean;
  v_analises integer := 0;
begin
  perform set_config('sqie.reason', 'Texto fiel ao caderno oficial do Inep (carga das provas corrigidas, revisão de 12/10/2026)', true);
  for r in select value from jsonb_array_elements(v_dados) loop
    select * into q from public.questions x where x.id = r ->> 'id' for update;
    if not found then
      insert into _carga_texto_resultado values ('revalida-2020', r ->> 'id', r ->> 'code', '-', 'pulado: questão não encontrada no banco');
      continue;
    end if;
    v_statement := q.statement;
    v_options := q.options;
    v_muda := false;
    for c in select key as campo, value as v from jsonb_each(r -> 'campos') loop
      v_atual := case when c.campo = 'statement' then q.statement
                      else (select o ->> 'text' from jsonb_array_elements(q.options) o where o ->> 'id' = c.campo limit 1) end;
      if v_atual is not distinct from (c.v ->> 'depois') or md5(v_atual) is not distinct from (c.v ->> 'sem_tabela_md5') then
        v_situacao := 'já estava corrigido';
      elsif v_atual is not null and md5(v_atual) = c.v ->> 'antes_md5' then
        v_situacao := 'corrigido agora';
        v_muda := true;
        if c.campo = 'statement' then
          v_statement := c.v ->> 'depois';
        else
          v_options := (select jsonb_agg(case when o ->> 'id' = c.campo then jsonb_set(o, '{text}', to_jsonb(c.v ->> 'depois')) else o end order by n)
                        from jsonb_array_elements(v_options) with ordinality as x (o, n));
        end if;
      else
        v_situacao := 'pulado: o texto no banco mudou depois de 12/10/2026';
      end if;
      insert into _carga_texto_resultado values ('revalida-2020', q.id, q.code, case c.campo when 'statement' then 'enunciado' else 'alternativa ' || c.campo end, v_situacao);
    end loop;
    if v_muda then
      v_analises := v_analises + (select count(*)::int from public.question_analysis a where a.question_id = q.id and a.is_current and a.status = 'published');
      update public.questions set statement = v_statement, options = v_options where id = q.id;
      perform public.admin_log('question.updated', q.id, jsonb_build_object('status', q.status, 'reason', 'Texto fiel ao caderno oficial do Inep (carga das provas corrigidas, revisão de 12/10/2026)'));
    end if;
  end loop;
  insert into _carga_texto_resultado values ('revalida-2020', '-', '-', 'análises', 'análises publicadas que saíram do ar: ' || v_analises);
  perform set_config('sqie.reason', '', true);
end
$carga_texto$;

select resultado, detalhe from (
  select 0 as ordem,
         case when count(*) filter (where situacao like 'pulado%') = 0 then 'OK: ' else 'ATENÇÃO: ' end
           || 'Revalida 2020: '
           || count(distinct questao) filter (where situacao = 'corrigido agora') || ' questões corrigidas agora ('
           || count(*) filter (where situacao = 'corrigido agora') || ' campos); '
           || count(*) filter (where situacao = 'já estava corrigido') || ' campos já estavam corrigidos; '
           || count(*) filter (where situacao like 'pulado%') || ' pulados (de 25)' as resultado,
         max(situacao) filter (where campo = 'análises') as detalhe
  from _carga_texto_resultado where prova = 'revalida-2020'
  union all
  select 1, 'PULADO: ' || codigo || ' (' || campo || ')', situacao
  from _carga_texto_resultado where prova = 'revalida-2020' and situacao like 'pulado%'
) x order by ordem, resultado;
